+/** Selects paths with an ordered list of glob patterns. See README.md for the syntax. */
+
+interface Entry {
+  raw: string;
+  negated: boolean;
+  segments: string[];
+  segmentRegexes: Array<RegExp | null>;
+}
+
+const REGEX_SPECIAL = new Set([".", "+", "^", "$", "{", "}", "(", ")", "|", "[", "]", "\\"]);
+
+function segmentToRegex(segment: string): RegExp {
+  let source = "";
+  for (const ch of segment) {
+    if (ch === "*") {
+      source += "[^/]*";
+    } else if (ch === "?") {
+      source += "[^/]";
+    } else {
+      source += REGEX_SPECIAL.has(ch) ? "\\" + ch : ch;
+    }
+  }
+  return new RegExp(`^${source}$`);
+}
+
+function matchSegments(segments: string[], regexes: Array<RegExp | null>, path: string[]): boolean {
+  const memo = new Map<number, Map<number, boolean>>();
+
+  const match = (pi: number, si: number): boolean => {
+    let byPi = memo.get(pi);
+    if (byPi !== undefined) {
+      const cached = byPi.get(si);
+      if (cached !== undefined) return cached;
+    } else {
+      byPi = new Map();
+      memo.set(pi, byPi);
+    }
+
+    let result: boolean;
+    if (pi === segments.length) {
+      result = si === path.length;
+    } else if (segments[pi] === "**") {
+      if (pi + 1 === segments.length) {
+        result = si < path.length;
+      } else {
+        const consume = si < path.length && match(pi, si + 1);
+        result = consume || match(pi + 1, si);
+      }
+
